        tag = 'today, ' if d == today else ''
        if d <= deadline and isbd(d):
            s = 'valid PTP date'
        elif d <= deadline:
            why = 'weekend' if d.weekday() >= 5 else 'bank holiday'
            s = why + ', not a valid PTP date; offer the next business day, ' + label(next_bd(d)) + ', instead'
        else:
